    ['name' => 'A.J. Cuseana Restaurant', 'town' => 'Casiguran', 'barangay' => 'Rizal', 'address' => 'Plancha, Rizal, Casiguran, Sorsogon, 4702', 'lat' => '12.882260', 'lng' => '124.024682', 'hours' => 'Open 24 hours', 'phone' => '0981 408 2322', 'price' => 'budget', 'cuisine' => 'Filipino', 'meals' => ['breakfast', 'lunch', 'merienda', 'dinner'], 'specialties' => 'Seafood rice platters, curry, seafood boil trays, and party platters of lumpia and fried chicken.', 'filled' => ['specialties', 'price'],
        'about' => 'A.J. Cuseana Restaurant in Plancha, Rizal, Casiguran, is a nipa-roofed bamboo restaurant set on a lawn among trees, with a hammock in its screened dining area. The kitchen plates seafood rice topped with shrimp, crab, mussels and squid, and curries garnished with carved vegetables, and it prepares seafood boil trays of shrimp, crab, clams, mussels and corn, plus party platters of lumpia and fried chicken. Open 24 hours, it is useful for early starts and late arrivals.'],

    // Castilla
    ['name' => 'Chill N Casa', 'town' => 'Castilla', 'barangay' => 'Cumadcad', 'address' => 'Purok Sunflower, Cumadcad, Castilla, Sorsogon', 'lat' => '12.979742', 'lng' => '123.794490', 'hours' => '12:00 PM – 10:00 PM', 'phone' => '0950 041 1429', 'price' => 'luxury', 'cuisine' => 'Filipino', 'meals' => ['lunch', 'merienda', 'dinner'], 'specialties' => 'Family-style platters such as pancit, chopsuey with quail eggs, sweet and sour fish, lechon kawali and sesame-glazed chicken; chicken burgers, loaded cheese fries and a full bar.', 'filled' => ['cuisine', 'specialties'],
        'about' => 'Chill N Casa in Purok Sunflower, Cumadcad, Castilla, is an air-conditioned restaurant with wood-slat walls, gold chiavari chairs and a bar stocked with spirits, soju and coffee syrups. Its function hall of round, dressed tables suits parties and gatherings. The kitchen sends out family-style platters such as pancit canton with lumpia and egg, chopsuey with quail eggs, sweet and sour fish, lechon kawali and sesame-glazed chicken, along with chicken burgers and loaded cheese fries. Open from noon to 10:00 PM.'],
    ['name' => 'Patio Sofia Bistro', 'town' => 'Castilla', 'barangay' => 'Cumadcad', 'address' => 'Sunflower Street, Cumadcad, Castilla, Sorsogon, 4713', 'lat' => '12.979821', 'lng' => '123.796065', 'hours' => '7:00 AM – 7:00 PM', 'phone' => '0991 581 3801', 'price' => 'budget', 'cuisine' => 'Filipino', 'meals' => ['breakfast', 'lunch', 'merienda'], 'specialties' => 'Pork a la carte (lechon kawali, sinigang, sisig, chicharon bituka), burgers and eggwiches, frappés and freakshakes, lemonades, beer buckets, wine and cocktail towers.', 'filled' => ['specialties'],
        'about' => 'Patio Sofia Bistro on Sunflower Street, Cumadcad, Castilla, is a garden bistro of covered patios under string lights, joined by stepping-stone paths through the plants, with a vine-draped dining area on gravel and an aquarium. Board games such as Jenga, Uno, chess and dominoes are on hand for groups. The menu runs from shareable pork dishes such as lechon kawali, pork sinigang and sizzling sisig to burgers and egg sandwiches, with frappés, freakshakes and lemonades, plus beer buckets, wine and cocktail towers.'],
    ['name' => 'Izakaya Restobar', 'town' => 'Castilla', 'barangay' => 'Cumadcad', 'address' => 'Purok Everlasting, Cumadcad, Castilla, Sorsogon', 'lat' => '12.978843', 'lng' => '123.789100', 'hours' => 'Monday to Sunday 6:00 AM – 12:00 midnight', 'phone' => '0927 742 3424 (Globe) / 0909 937 3216 (Smart)', 'price' => 'moderate', 'cuisine' => 'Filipino KTV Restobar', 'meals' => ['breakfast', 'lunch', 'merienda', 'dinner'], 'specialties' => 'Beef salpicao and garlic pepper beef, bulalo, sisig, honey chicken, flavored chicken, pasta, pansit and lomi overload; combo party trays, lechon and catering.', 'filled' => ['cuisine', 'specialties'],
        'about' => 'Izakaya, which its menu calls Izakaya KTV Bar & Restaurant, is in Purok Everlasting, Cumadcad, Castilla, with karaoke alongside its kitchen and bar. The menu covers beef dishes such as salpicao, garlic pepper beef and bulalo, sisig in pork, tuna and chicken liver versions, honey chicken and flavored chicken in buffalo, parmesan or salted egg, pastas, pansit, and a lomi overload topped with crispy pork and chicharon. It also makes combo party trays, roasts lechon and accepts catering for events. Open every day from 6:00 AM to midnight.'],

